import { useState } from "react";
import axios from "axios";
import { T } from "./constants";

export default function LoginPage({ onLogin }) {
  const [email, setEmail] = useState("");
  const [pass, setPass] = useState("");
  const [err, setErr] = useState("");
  const [loading, setLoading] = useState(false);

  const submit = async () => {
    if (!email || !pass) {
      setErr("يرجى إدخال البريد الإلكتروني وكلمة المرور");
      return;
    }

    try {
      setLoading(true);
      setErr("");

      // API Request
      const response = await axios.post(
        "http://localhost:8000/login",
        {
          email: email,
          password: pass,
        },
        {
          withCredentials: true, // important for session cookies
        }
      );

      // success login
      if (response.status === 200) {
        onLogin(response.data.user);
      }
    } catch (error) {
      console.log(error);

      if (error.response?.data?.message) {
        setErr(error.response.data.message);
      } else {
        setErr("حدث خطأ أثناء تسجيل الدخول");
      }
    } finally {
      setLoading(false);
    }
  };

  const styles = {
    root: {
      minHeight: "100vh",
      background:
        "linear-gradient(135deg, #1a0000 0%, #B71C1C 50%, #7B0000 100%)",
      display: "flex",
      alignItems: "center",
      justifyContent: "center",
      fontFamily: "'Cairo', sans-serif",
      direction: "rtl",
      padding: "20px",
      position: "relative",
      overflow: "hidden",
    },
    pattern: {
      position: "absolute",
      inset: 0,
      opacity: 0.04,
      backgroundImage:
        "repeating-linear-gradient(45deg,#fff 0,#fff 1px,transparent 0,transparent 50%)",
      backgroundSize: "18px 18px",
      pointerEvents: "none",
    },
    watermark: {
      position: "absolute",
      right: "-40px",
      bottom: "-60px",
      fontFamily: "'Noto Serif SC', serif",
      fontSize: "280px",
      color: "rgba(255,255,255,0.04)",
      fontWeight: 700,
      lineHeight: 1,
      pointerEvents: "none",
      userSelect: "none",
    },
    card: {
      background: "#fff",
      borderRadius: "20px",
      padding: "48px 44px",
      width: "100%",
      maxWidth: "420px",
      boxShadow: "0 24px 80px rgba(0,0,0,0.35)",
      position: "relative",
      zIndex: 2,
    },
    logoRow: {
      display: "flex",
      alignItems: "center",
      gap: "12px",
      marginBottom: "32px",
      justifyContent: "center",
    },
    zh: {
      fontFamily: "'Noto Serif SC', serif",
      fontSize: "28px",
      color: T.gold,
      letterSpacing: "3px",
    },
    title: {
      fontSize: "22px",
      fontWeight: 800,
      color: T.ink,
      textAlign: "center",
      marginBottom: "4px",
    },
    sub: {
      fontSize: "13px",
      color: T.muted,
      textAlign: "center",
      marginBottom: "32px",
    },
    label: {
      fontSize: "13px",
      fontWeight: 700,
      color: T.inkSoft,
      marginBottom: "6px",
      display: "block",
    },
    input: {
      width: "100%",
      padding: "12px 14px",
      border: `1.5px solid ${T.border}`,
      borderRadius: "10px",
      fontSize: "14px",
      fontFamily: "'Cairo', sans-serif",
      color: T.ink,
      background: T.bg,
      outline: "none",
      marginBottom: "18px",
      transition: "border-color .2s",
      direction: "rtl",
    },
    btn: {
      width: "100%",
      padding: "13px",
      background: T.red,
      color: "#fff",
      border: "none",
      borderRadius: "10px",
      fontSize: "15px",
      fontWeight: 700,
      fontFamily: "'Cairo', sans-serif",
      cursor: "pointer",
      marginTop: "8px",
      transition: "all .2s",
    },
    err: {
      background: T.redLight,
      color: T.red,
      borderRadius: "8px",
      padding: "10px 14px",
      fontSize: "13px",
      marginTop: "14px",
      textAlign: "center",
    },
  };

  return (
    <div style={styles.root}>
      <div style={styles.pattern} />

      <div style={styles.watermark}>孔</div>

      <div style={styles.card}>
        <div style={styles.logoRow}>
          <span style={styles.zh}>孔子学院</span>
        </div>

        <div style={styles.title}>لوحة تحكم الإدارة</div>
        <div style={styles.sub}>معهد كونفوشيوس — جامعة القاهرة</div>

        <label style={styles.label}>البريد الإلكتروني</label>

        <input
          type="email"
          style={styles.input}
          value={email}
          onChange={(e) => {
            setEmail(e.target.value);
            setErr("");
          }}
          placeholder="أدخل البريد الإلكتروني"
          onKeyDown={(e) => e.key === "Enter" && submit()}
        />

        <label style={styles.label}>كلمة المرور</label>

        <input
          type="password"
          style={styles.input}
          value={pass}
          onChange={(e) => {
            setPass(e.target.value);
            setErr("");
          }}
          placeholder="أدخل كلمة المرور"
          onKeyDown={(e) => e.key === "Enter" && submit()}
        />

        <button
          style={{
            ...styles.btn,
            opacity: loading ? 0.7 : 1,
          }}
          onClick={submit}
          disabled={loading}
        >
          {loading ? "جاري التحقق..." : "تسجيل الدخول"}
        </button>

        {err && <div style={styles.err}>⚠️ {err}</div>}
      </div>
    </div>
  );
}
